+			new_polygon.points.push_back({ closest_start_point, get_point_key(closest_start_point, merge_rasterizer_cell_size) });
+			new_polygon.points.push_back({ closest_start_point, get_point_key(closest_start_point, merge_rasterizer_cell_size) });
+			new_polygon.points.push_back({ closest_end_point, get_point_key(closest_end_point, merge_rasterizer_cell_size) });
+			new_polygon.points.push_back({ closest_end_point, get_point_key(closest_end_point, merge_rasterizer_cell_size) });
