+	polygon_count = 0;
+	navmesh_polygons_count = 0;
+	for (NavRegionIteration &region : map_iteration->region_iterations) {
+		for (gd::Polygon &region_polygon : region.navmesh_polygons) {
+			region_polygon.id = polygon_count;
