+		for (uint32_t j = 0; j < iter_free_edges.size(); j++) {
+			const gd::Edge::Connection &other_edge = iter_free_edges[j];
+			if (i == j || free_edge.polygon->owner == other_edge.polygon->owner) {
+				continue;
+			}
